function batchRanges(maxId, batchSize) {
  const ranges = [];
  let lo = 1;
  while (lo <= maxId) {
    const hi = Math.min(lo + batchSize, maxId); // BUG: lo+batchSize, not lo+batchSize-1
    ranges.push([lo, hi]);
    lo = hi + 2;                                 // BUG: skips the id right after hi
  }
  return ranges;
}

